INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(53211, 'Zechariah 7:5', 'Zechariah', 7, 5, '”د دې مُلک د ټولو خلقو نه او اِمامانو نه پوښتنه وکړه، کله چې تاسو روژه نيوله او ماتم مو په پينځمه او اوومه مياشت کښې د تېرو اويا کالو راسې کولو، آيا دا روژې په حقيقت تاسو زما دپاره نيولې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah7_verse_5.mp3', '', 1761754199, 1761754199),
(53212, 'Zechariah 7:6', 'Zechariah', 7, 6, 'او کله چې تاسو خوراک څښاک کولو، آيا دا تاسو د ځان دپاره نۀ کولو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah7_verse_6.mp3', '', 1761754199, 1761754199),
(53213, 'Zechariah 7:7', 'Zechariah', 7, 7, 'آيا دا هغه کلام نۀ دے چې ما مالِک خُدائ فرمائيلى وُو د وړومبيو پېغمبرانو په ذريعه کله چې په يروشلم او د دې نه ګېرچاپېره کلو کښې سکون او برکت وو، او نجب او د مغربى غرونو لمنې ښۀ آبادې وې؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah7_verse_7.mp3', '', 1761754199, 1761754199),
(53214, 'Zechariah 7:8', 'Zechariah', 7, 8, 'او د مالِک خُدائ ربُ الافواج کلام بيا په زکرياه نازل شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah7_verse_8.mp3', '', 1761754199, 1761754199),
(53215, 'Zechariah 7:9', 'Zechariah', 7, 9, '”دا مالِک خُدائ ربُ الافواج فرمائى، په رښتيا سره اِنصاف کوئ، يو بل سره رحم او مينه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah7_verse_9.mp3', '', 1761754199, 1761754199),
(53216, 'Zechariah 7:10', 'Zechariah', 7, 10, 'په کونډو، يتيمانو، په پردو او غريبانانو ظلم زياتے مۀ کوئ. په خپلو زړونو کښې يو بل ته شېطانى سوچونه مۀ کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah7_verse_10.mp3', '', 1761754199, 1761754199),
(53217, 'Zechariah 7:11', 'Zechariah', 7, 11, 'خو هغوئ په دې غور کولو نه اِنکار وکړو، او په سرکشۍ سره يې ورته شا کړه او خپل غوږونه يې بند کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah7_verse_11.mp3', '', 1761754199, 1761754199),
(53218, 'Zechariah 7:12', 'Zechariah', 7, 12, 'هغوئ خپل زړونه لکه د هيرې سخت کاڼى په شان سخت کړل او هغوئ هغه حکمونو يا تعليماتو ته توجو نۀ ورکوله چې مالِک خُدائ ربُ الافواج د خپل روح نه د پخوانو پېغمبرانو په ذريعه رالېږلى وُو، نو په دې وجه مالِک خُدائ ربُ الافواج سخت په قهر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah7_verse_12.mp3', '', 1761754199, 1761754199),
(53219, 'Zechariah 7:13', 'Zechariah', 7, 13, 'کله چې ما ورته آواز وکړو، نو هغوئ نۀ اورېدلو، او نو اوس کله چې هغوئ آواز وکړى، نو زۀ به يې نۀ اورم، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah7_verse_13.mp3', '', 1761754199, 1761754199),
(53220, 'Zechariah 7:14', 'Zechariah', 7, 14, 'ما هغوئ د طوفان په ذريعه په لرى قومونو کښې خوارۀ وارۀ کړل، چرته چې هغوئ لکه د پردو په شان اوسېدل. د هغوئ مُلک وران ويجاړ پروت وُو او د هغوئ نه پس ورته څوک نۀ شو راتلے. نو دغه شان د هغوئ خپل ښکلے مُلک په صحرا بدل شو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah7_verse_14.mp3', '', 1761754199, 1761754199),
(53221, 'Proverbs 8:1', 'Proverbs', 8, 1, 'حکمت د یوې هوښیارې ښځې په څېر نارې وهي او پوهه په لوړ اواز خپل غږ پورته کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_1.mp3', '', 1761754199, 1761754199),
(53222, 'Proverbs 8:2', 'Proverbs', 8, 2, 'هغه د لارې په غاړه په لوړو ځایونو ولاړه وي او د څلور لارو په سر ودریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_2.mp3', '', 1761754199, 1761754199),
(53223, 'Proverbs 8:3', 'Proverbs', 8, 3, 'هغه د ښار د دروازو دننه د تګ راتګ د لارو په خوا کې نارې وهي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_3.mp3', '', 1761754199, 1761754199),
(53224, 'Proverbs 8:4', 'Proverbs', 8, 4, '«ای سړیو! زه په تاسو ټولو ته غږ کوم او په تاسو ټولو باندې اواز کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_4.mp3', '', 1761754199, 1761754199),
(53225, 'Proverbs 8:5', 'Proverbs', 8, 5, 'ای ساده خلکو! په خپل ځان کې ځیرکتیا پیدا کړئ! ای کم‌عقلانو! د ښو او بدو ترمنځ فرق وکړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_5.mp3', '', 1761754199, 1761754199),
(53226, 'Proverbs 8:6', 'Proverbs', 8, 6, 'غوږ ونیسئ! زه ستاسو دپاره ښې خبرې لرم چې په رښتینې ژبه به یې درته بیان کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_6.mp3', '', 1761754199, 1761754199),
(53227, 'Proverbs 8:7', 'Proverbs', 8, 7, 'زه چې څه په خوله وایم، هغه رښتیا دي او ژبه مې له بدو خبرو نه کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_7.mp3', '', 1761754199, 1761754199),
(53228, 'Proverbs 8:8', 'Proverbs', 8, 8, 'د خولې ټولې خبرې مې سمې دي یوه هم په کې کږه او غولوونکې نه ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_8.mp3', '', 1761754199, 1761754199),
(53229, 'Proverbs 8:9', 'Proverbs', 8, 9, 'چې عقلمن انسان ته ټولې روښانه دي څوک چې علم لري نو پوهیږي چې دا خبرې سمې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_9.mp3', '', 1761754199, 1761754199),
(53230, 'Proverbs 8:10', 'Proverbs', 8, 10, 'د سپینو زرو په ځای زما نصیحت غوره کړئ او د سوچه سرو زرو په ځای علم حاصل کړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_10.mp3', '', 1761754199, 1761754199),
(53231, 'Proverbs 8:11', 'Proverbs', 8, 11, 'ځکه حکمت د لعلونو نه ډېر قیمتي دی چې له ارزښت سره یې ستا د خوښې هېڅ شی برابر نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_11.mp3', '', 1761754199, 1761754199),
(53232, 'Proverbs 8:12', 'Proverbs', 8, 12, 'زه حکمت یم او له ځیرکتیا سره یو ځای اوسېږم او علم او لیاقت تر‌لاسه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_12.mp3', '', 1761754199, 1761754199),
(53233, 'Proverbs 8:13', 'Proverbs', 8, 13, 'له څښتن څخه وېره له شرارت نه نفرت کول دي نو ځکه له کبر، غرور، بدۍ او کږو خبرو نه کرکه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_13.mp3', '', 1761754199, 1761754199),
(53234, 'Proverbs 8:14', 'Proverbs', 8, 14, 'مشوره او حکمت زما کار دی زه عقلمن یم او زما سره قدرت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_14.mp3', '', 1761754199, 1761754199),
(53235, 'Proverbs 8:15', 'Proverbs', 8, 15, 'پاچاهان زما په مرسته پاچاهي کوي او حکمرانان د انصاف پرېکړې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_15.mp3', '', 1761754199, 1761754199),
(53236, 'Proverbs 8:16', 'Proverbs', 8, 16, 'شهزادګان زما په مرسته حکومت کوي واکداران او ټول عادل قاضیان پرېکړې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_16.mp3', '', 1761754199, 1761754199),
(53237, 'Proverbs 8:17', 'Proverbs', 8, 17, 'زه له خپلو مینوالو سره مینه کوم څوک چې ما لټوي نو ما پیدا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_17.mp3', '', 1761754199, 1761754199),
(53238, 'Proverbs 8:18', 'Proverbs', 8, 18, 'دولت او عزت زما سره دی عدالت او تلپاتې شتمني زما ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_18.mp3', '', 1761754199, 1761754199),
(53239, 'Proverbs 8:19', 'Proverbs', 8, 19, 'زه د خالصو سرو زرو نه غوره مېوه ورکوم چې حاصل یې له سوچه سپینو زرو نه بهتر دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_19.mp3', '', 1761754199, 1761754199),
(53240, 'Proverbs 8:20', 'Proverbs', 8, 20, 'د عدالت په لاره روان یم او د انصاف په لارو تګ کوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_20.mp3', '', 1761754199, 1761754199),
(53241, 'Proverbs 8:21', 'Proverbs', 8, 21, 'نو ځکه خپلو مینوالو ته شتمني ورکوم او د هغوی خزانې ډکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_21.mp3', '', 1761754199, 1761754199),
(53242, 'Proverbs 8:22', 'Proverbs', 8, 22, 'څښتن له ټولو نه لومړی چې نور څه یې لا نه وو پیدا کړی، له هرڅه نه مخکې زه پیدا کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_22.mp3', '', 1761754199, 1761754199),
(53243, 'Proverbs 8:23', 'Proverbs', 8, 23, 'له ازله یې زما د بدن برخې یوځای کړلې او د دنیا له جوړېدو او د هرڅه نه مخکې زه موجود وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_23.mp3', '', 1761754199, 1761754199),
(53244, 'Proverbs 8:24', 'Proverbs', 8, 24, 'کله چې لا ژور دریابونه نه وو پیدا شوي او له چینو څخه اوبه نه وې راوتلې زه زېږېدلی وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_24.mp3', '', 1761754199, 1761754199),
(53245, 'Proverbs 8:25', 'Proverbs', 8, 25, 'مخکې له دی چې غرونه په خپل ځای ودریږي او غونډۍ رامنځته شي زه زېږېدلی وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_25.mp3', '', 1761754199, 1761754199),
(53246, 'Proverbs 8:26', 'Proverbs', 8, 26, 'مخکې له دی چې څښتن ځمکه او پراخه کروندې جوړ کړي او د دنیا لومړنۍ خاوره پیدا کړي زه زېږېدلی وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_26.mp3', '', 1761754199, 1761754199),
(53247, 'Proverbs 8:27', 'Proverbs', 8, 27, 'کله چې هغه اسمانونه په خپل ځای ودرول او د دریاب په مخ یې د اسمان لمن راچاپېر کړه زه هلته وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_27.mp3', '', 1761754199, 1761754199),
(53248, 'Proverbs 8:28', 'Proverbs', 8, 28, 'کله چې هغه په اسمان کې ورېځې ځای په ځای کړې او د ځمکې په مخ یې چینې روانې کړې زه حاضر وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_28.mp3', '', 1761754199, 1761754199),
(53249, 'Proverbs 8:29', 'Proverbs', 8, 29, 'کله چې هغه دریابونو ته خپل حدود وټاکل چې اوبه یې له حکم نه سرغړونه ونه کړي او د ځمکې بنیاد یې کېښود زه هلته وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_29.mp3', '', 1761754199, 1761754199),
(53250, 'Proverbs 8:30', 'Proverbs', 8, 30, 'زه هر وخت د هغه په څنګ کې وم او زه هره ورځ خوشحالېدم او تل د هغه په حضور کې خوشحاله وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_30.mp3', '', 1761754199, 1761754199),
(53251, 'Proverbs 8:31', 'Proverbs', 8, 31, 'د نړۍ په ټوله ځمکه کې یې خوشحاله وم او د ټولو انسانانو نه خوشحالېدم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_31.mp3', '', 1761754199, 1761754199),
(53252, 'Proverbs 8:32', 'Proverbs', 8, 32, 'نو ای زما زامنو! اوس ماته غوږ ونیسئ بختور دي هغوی چې زما په لارو ځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_32.mp3', '', 1761754199, 1761754199),
(53253, 'Proverbs 8:33', 'Proverbs', 8, 33, 'زما نصیحت ته غوږ شئ او حکمت پیدا کړئ هغه له پام نه مه غورځوئ او مخ ترې مه اړوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_33.mp3', '', 1761754199, 1761754199),
(53254, 'Proverbs 8:34', 'Proverbs', 8, 34, 'بختور دی هغه څوک چې ماته غوږ نیسي او هره ورځ زما د کور په مخکې ولاړ وي او زما د دروازې په خوله کې انتظار وباسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_34.mp3', '', 1761754199, 1761754199),
(53255, 'Proverbs 8:35', 'Proverbs', 8, 35, 'ځکه څوک چې ما پیدا کړي نو ژوند پیدا کوي او د څښتن رضا او خوشحالي حاصلوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_35.mp3', '', 1761754199, 1761754199),
(53256, 'Proverbs 8:36', 'Proverbs', 8, 36, 'خو څوک چې ما نه پیدا کوي له ځان سره ظلم کوي هرڅوک چې زما نه کرکه کوي له مرګ سره مینه کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs8_verse_36.mp3', '', 1761754199, 1761754199),
(53257, 'Deuteronomy 15:1', 'Deuteronomy', 15, 1, 'د هر اووم کال په پای کې باید تاسو د خپلو پوروړیو پورونه وروبخښئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_1.mp3', '', 1761754199, 1761754199),
(53258, 'Deuteronomy 15:2', 'Deuteronomy', 15, 2, 'دا کار به په دې ډول کیږي: ستاسو څخه هرڅوک چې کوم بل اسراییلي ته یې پیسې په پور ورکړې وي باید د هغه پور وروبخښي. هغه دې د هغه اسراییلي څخه دا پیسې بېرته ونه غواړي، ځکه چې څښتن په خپله دا پور بخښل شوی اعلان کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_2.mp3', '', 1761754199, 1761754199),
(53259, 'Deuteronomy 15:3', 'Deuteronomy', 15, 3, 'تاسو کولای شئ چې د یو پردي څخه خپل پور واخلئ، خو باید د خپلو خلکو څخه پور بېرته ونه غواړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_3.mp3', '', 1761754199, 1761754199),
(53260, 'Deuteronomy 15:7', 'Deuteronomy', 15, 7, 'که چېرې ستاسو د خاورې په کوم ښار کې چې ستاسو څښتن خدای یې درکوي کوم بل اسراییلی وي چې محتاج وي، نو زړه مه سختوئ او د هغه سره د مرستې کولو څخه انکار مه کوئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_7.mp3', '', 1761754199, 1761754199),
(53261, 'Deuteronomy 15:8', 'Deuteronomy', 15, 8, 'بلکې سخي اوسئ او څومره پیسو ته چې اړتیا ولري په پور یې ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_8.mp3', '', 1761754199, 1761754199),
(53262, 'Deuteronomy 15:9', 'Deuteronomy', 15, 9, 'پام کوئ چې د خپل ځان سره داسې ونه وایئ چې اووم کال به زر راورسیږي بیا به زه ونه شم کولای چې خپلې پیسې بېرته واخلم. که تاسو داسې فکر وکړئ، نو دا به ډېره بده وي چې د هغه غریب سره د مرستې کولو څخه انکار وکړئ. که چېرې د هغه سره مرسته ونه کړئ هغه به ستاسو په خلاف څښتن ته فریاد وکړي او تاسو به ګناهکار وګڼل شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_9.mp3', '', 1761754199, 1761754199),
(53263, 'Deuteronomy 15:10', 'Deuteronomy', 15, 10, 'هغه چې هرڅه ته اړتیا لري، هغه ورته په وړیا توګه او د پېرزوینې له مخې ورکړئ، نو څښتن به تاسو ته په هر کار کې برکت درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_10.mp3', '', 1761754199, 1761754199),
(53264, 'Deuteronomy 15:11', 'Deuteronomy', 15, 11, 'تل به ځینې غریب او محتاج اسراییلیان موجود وي، نو زه تاسو ته امر کوم چې د هغوی سره د سخاوت څخه کار واخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_11.mp3', '', 1761754199, 1761754199),
(53265, 'Deuteronomy 15:12', 'Deuteronomy', 15, 12, 'که چېرې کوم نارینه یا ښځینه عبرانی خپل ځان په تاسو باندې د غلام په توګه خرڅ کړي او شپږ کاله ستاسو خدمت وکړي، نو په اووم کال باید هغه پرېږدئ چې ازاد شي او لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_12.mp3', '', 1761754199, 1761754199),
(53266, 'Deuteronomy 15:13', 'Deuteronomy', 15, 13, 'د ازادېدلو په وخت کې هغه تش لاس مه لېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_13.mp3', '', 1761754199, 1761754199),
(53267, 'Deuteronomy 15:14', 'Deuteronomy', 15, 14, 'څومره چې څښتن د برکت په توګه درکړي دي د هغو څخه د سخاوت له مخې ورته ورکړئ یعنې پسونه، وزې، غلې دانې او شراب.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_14.mp3', '', 1761754199, 1761754199),
(53268, 'Deuteronomy 15:15', 'Deuteronomy', 15, 15, 'په یاد لرئ چې تاسو په مصر کې غلامان وئ او خپل څښتن خدای ازاد کړئ، نو په دې خاطر زه نن تاسو ته دا امر کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_15.mp3', '', 1761754199, 1761754199),
(53269, 'Deuteronomy 15:16', 'Deuteronomy', 15, 16, 'خو کېدای شي چې ستاسو غلام ونه غواړي چې لاړ شي. کېدای شي چې هغه تاسو او ستاسو د کورنۍ سره مینه ولري او د هغه دپاره به ډېره ښه وي چې ستاسو سره پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_16.mp3', '', 1761754199, 1761754199),
(53270, 'Deuteronomy 15:17', 'Deuteronomy', 15, 17, 'بیا هغه د خپل کور دروازې ته بوځئ او هلته د هغه غوږ په ستنه باندې سوری کړئ، بیا به هغه ټول عمر ستاسو غلام وي. د ښځینه غلامانو سره هم همداسې کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_17.mp3', '', 1761754199, 1761754199),
(53271, 'Deuteronomy 15:18', 'Deuteronomy', 15, 18, 'کله چې تاسو یو غلام ازادوئ، نو خفه کېږئ مه. اخر هغه د مزدور په نیمه بیه شپږ کاله ستاسو خدمت کړی دی. که چېرې داسې وکړئ، نو تاسو ته به خپل څښتن خدای په هر کار کې برکت درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_18.mp3', '', 1761754199, 1761754199),
(53272, 'Deuteronomy 15:19', 'Deuteronomy', 15, 19, 'د خپل څښتن خدای دپاره د خپلو پادو او رمو څخه ټول لومړني زېږېدل شوي نران بېل کړئ. د لومړنیو زېږېدل شویو غویانو څخه کار مه اخلئ او لومړني زېږېدل شوي پسونه مه سکولئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_19.mp3', '', 1761754199, 1761754199),
(53273, 'Deuteronomy 15:20', 'Deuteronomy', 15, 20, 'هر کال باید تاسو او ستاسو کورنۍ د هغو غوښه د څښتن په حضور کې یعنې په هغه ځای کې وخورئ چې هغه یې د خپل عبادت دپاره غوره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_20.mp3', '', 1761754199, 1761754199),
(53274, 'Deuteronomy 15:21', 'Deuteronomy', 15, 21, 'خو که چېرې په حیواناتو کې کوم عیب وي، هغه معیوب یا ړوند وي یا کوم بل غټ عیب ولري، تاسو باید هغه خپل څښتن خدای ته قرباني نه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_21.mp3', '', 1761754199, 1761754199),
(53275, 'Deuteronomy 15:22', 'Deuteronomy', 15, 22, 'تاسو کولای شئ چې د داسې حیواناتو غوښه په خپل کور کې وخورئ. تاسو ټول که په مذهبي لحاظ پاک یئ یا ناپاک، کولای شئ چې د هغو حیواناتو غوښه داسې وخورئ لکه څنګه چې د هوسۍ یا غرڅه غوښه خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_22.mp3', '', 1761754199, 1761754199),
(53276, 'Deuteronomy 15:23', 'Deuteronomy', 15, 23, 'خو تاسو باید هېڅکله د حیوان وینه ونه خورئ، بلکې هغه د اوبو په شان په ځمکه باندې توی کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy15_verse_23.mp3', '', 1761754199, 1761754199),
(53277, 'Daniel 3:1', 'Daniel', 3, 1, 'نبوکدنضر بادشاه يوه د سرو زرو مجسمه جوړه کړه چې لس کم سل فټه اوچته او نهۀ فټه پلنه وه، او هغۀ هغه د بابل په صوبه کښې د دُورا په مېدان کښې ودروله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_1.mp3', '', 1761754199, 1761754199),
(53278, 'Daniel 3:2', 'Daniel', 3, 2, 'نو بيا بادشاه ټولو حکمرانانو، مشيرانو، خزانچيانو، قاضيانو او د صوبو آفسرانو ته پېغام ولېږلو چې د مجسمې د لګولو مراسمو له راشئ کومه چې هغۀ ودرولې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_2.mp3', '', 1761754199, 1761754199),
(53279, 'Daniel 3:3', 'Daniel', 3, 3, 'نو بيا ټول حکمرانان، مشيران، خزانچيان، قاضيان، او د صوبې نور آفسران د مجسمې د وقف کېدو رسم له راغونډ شول کومه چې نبوکدنضر بادشاه ودرولې وه او د هغې په وړاندې هغوئ ودرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_3.mp3', '', 1761754199, 1761754199),
(53280, 'Daniel 3:4', 'Daniel', 3, 4, 'نو بيا ډندورچى په اوچت آواز اعلان وکړو، ”اے د ټولو قومونو، ذاتونو او ژبو خلقو، تاسو ته دا حکم دے چې هغه ضرور سر ته ورسوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_4.mp3', '', 1761754199, 1761754199),
(53281, 'Daniel 3:5', 'Daniel', 3, 5, 'څنګه چې تاسو د بيګل، شپيلۍ، رباب، بينجو، سريندې، ستار او هر قسمه موسيقۍ او سازونو آواز واورئ نو هغه د سرو زرو مجسمې ته عبادت او سجده وکړئ کومه چې نبوکدنضر بادشاه ودرولې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_5.mp3', '', 1761754199, 1761754199),
(53282, 'Daniel 3:6', 'Daniel', 3, 6, 'هر هغه څوک چې عبادت او سجده ونۀ کړى نو هغه به سمدستى د اور په لمبه بټۍ کښې وغورزولے شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_6.mp3', '', 1761754199, 1761754199),
(53283, 'Daniel 3:7', 'Daniel', 3, 7, 'نو هرکله چې هغوئ د بيګل، شپيلۍ، رباب، بينجو، سريندې، ستار او هر قسمه موسيقۍ او سازونو آواز واورېدو، نو د ټولو خلقو او ټولو قومونو او د هرې ژبې خلقو، هغه د سرو زرو مجسمې ته سجده وکړه او د هغې عبادت يې وکړو، کومه چې نبوکدنضر بادشاه ودرولې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_7.mp3', '', 1761754199, 1761754199),
(53284, 'Daniel 3:8', 'Daniel', 3, 8, 'نو په دې موقع څۀ نجوميان بادشاه له ورغلل او د يهوديانو خلاف يې سخت شکايت وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_8.mp3', '', 1761754199, 1761754199),
(53285, 'Daniel 3:9', 'Daniel', 3, 9, 'هغوئ نبوکدنضر بادشاه ته ووئيل چې، ”اے بادشاه، تۀ دې د تل دپاره ژوندے يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_9.mp3', '', 1761754199, 1761754199),
(53286, 'Daniel 3:10', 'Daniel', 3, 10, 'اے بادشاه سلامت، تاسو يو فرمان جارى کړے دے، هغه دا چې هر څوک چې د بيګل، شپيلۍ، رباب، بينجو، سريندې، ستار او هر قسمه موسيقۍ او سازونو آواز واورى هغوئ دې د سرو زرو مجسمې ته سجده وکړى او د هغې عبادت دې وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_10.mp3', '', 1761754199, 1761754199),
(53287, 'Daniel 3:11', 'Daniel', 3, 11, 'او هر څوک چې دې مجسمې ته سجده ونۀ کړى او د هغې عبادت ونۀ کړى، نو هغه به د بل شوې اور بټۍ ته ضرور وغورزولے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_11.mp3', '', 1761754199, 1761754199),
(53288, 'Daniel 3:12', 'Daniel', 3, 12, 'خو اے بادشاه سلامت، دلته يو څو يهوديان دى څوک چې تا د بابل په صوبې باندې مشران مقرر کړى دى، شدرک، ميشک او عبدنجو، څوک چې تا له توجو نۀ درکوى. نۀ هغوئ ستا د معبودانو خِدمت کوى او نۀ د هغه سرو زرو د مجسمې عبادت کوى کومه چې تا ودرولې ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_12.mp3', '', 1761754199, 1761754199),
(53289, 'Daniel 3:13', 'Daniel', 3, 13, 'نو بيا په دې باندې بادشاه ډېر غصه شو او حکم يې وکړو چې سمدستى شدرک، ميشک، او عبدنجو ما ته حاضر کړئ. نو دا کسان بادشاه له راوستلے شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_13.mp3', '', 1761754199, 1761754199),
(53290, 'Daniel 3:14', 'Daniel', 3, 14, 'نو بيا نبوکدنضر هغوئ ته ووئيل، ”شدرک، ميشک او عبدنجو ولې دا خبره رښتيا ده چې تاسو زما د معبودانو خِدمت او د هغه سرو زرو د مجسمې عبادت نۀ کوئ کومه چې ما ودرولې ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_14.mp3', '', 1761754199, 1761754199),
(53291, 'Daniel 3:15', 'Daniel', 3, 15, 'اوس کله چې تاسو د بيګل، شپيلۍ، رباب، بينجو، سريندې، ستار او هر قسمه موسيقۍ او سازونو آواز واورئ، نو کۀ چرې تاسو دې ته تيار يئ چې هغه د سرو زرو د مجسمې په وړاندې ټيټ شئ او د هغې عبادت وکړئ کومه چې ما جوړه کړې ده، نو ډېره ښۀ ده. خو کۀ چرې تاسو د هغې عبادت ونۀ کړئ نو تاسو به سمدستى د اور بټۍ ته وغورزولے شئ. نو کوم يو معبود به تاسو زما د لاسه خلاص کړى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_15.mp3', '', 1761754199, 1761754199),
(53292, 'Daniel 3:16', 'Daniel', 3, 16, 'شدرک، ميشک او عبدنجو بادشاه ته جواب ورکړو، ”اے نبوکدنضره، مونږ ته د دې ضرورت نشته چې ستا نه په دې معامله کښې د خپل ځان ساتنه وکړُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_16.mp3', '', 1761754199, 1761754199),
(53293, 'Daniel 3:17', 'Daniel', 3, 17, 'اے بادشاه کۀ چرې مونږ د بل شوې اور بټۍ ته وغورزولے شُو، نو د کوم خُدائ پاک چې مونږ خِدمت کوُو هغه دا کولے شى چې مونږ د هغې نه وساتى، او هغه به مونږ ستا د لاسونو نه بچ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_17.mp3', '', 1761754199, 1761754199),
(53294, 'Daniel 3:18', 'Daniel', 3, 18, 'اے بادشاه سلامت، خو کۀ چرې هغه مونږ ستا نه بچ هم نۀ کړى، خو تۀ په دې پوهه شه چې مونږ به نۀ ستا د معبودانو عبادت او نۀ د هغه سرو زرو د مجسمې عبادت وکړُو کومه چې تا ودرولې ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_18.mp3', '', 1761754199, 1761754199),
(53295, 'Daniel 3:19', 'Daniel', 3, 19, 'نو بيا نبوکدنضر شدرک، ميشک او عبدنجو ته ډېر سخت غصه شو، او د غصې نه د هغۀ رنګ تک سور شو. او هغۀ حکم وکړو چې هغه د اور بټۍ د پخوا نه اووۀ ځله زياته ګرمه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_19.mp3', '', 1761754199, 1761754199),
(53296, 'Daniel 3:20', 'Daniel', 3, 20, 'او هغۀ په خپل فوج کښې څو تکړه کسانو ته حکم وکړو چې شدرک، ميشک او عبدنجو کلک وتړئ او په بټۍ کښې يې د اور لمبو ته وغورزوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_20.mp3', '', 1761754199, 1761754199),
(53297, 'Daniel 3:21', 'Daniel', 3, 21, 'نو بيا هغوئ هغه درې واړه کسان د خپلو قميصونو، پرتوګونو، چوغو او پټکو سره وتړل او د اور لمبو ته يې په بټۍ کښې وروغورزول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_21.mp3', '', 1761754199, 1761754199),
(53298, 'Daniel 3:22', 'Daniel', 3, 22, 'خو د بادشاه حکم ډېر زورَور وو او بټۍ ډېره زياته ګرمه شوې وه نو ځکه د اور شغلو هغه فوجيان وسوزول او مړۀ يې کړل چا چې شدرک، ميشک او عبدنجو د اور په بټۍ کښې وغورزول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_22.mp3', '', 1761754199, 1761754199),
(53299, 'Daniel 3:23', 'Daniel', 3, 23, 'نو دا درې کسان کلک تړلے شوى وُو او د اور بټۍ کښې يې وغورزول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_23.mp3', '', 1761754199, 1761754199),
(53300, 'Daniel 3:24', 'Daniel', 3, 24, 'سمدستى په حېرانتيا سره نبوکدنضر راپاڅېدو او هغۀ د خپلو مشيرانو نه تپوس وکړو، ”ولې مونږ درې کسان نۀ وُو تړلى او په دې بټۍ کښې مو نۀ وُو غورزولى څۀ؟“ په جواب کښې هغوئ ورته ووئيل چې، ”آو جې، اے بادشاه سلامت.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_24.mp3', '', 1761754199, 1761754199),
(53301, 'Daniel 3:25', 'Daniel', 3, 25, 'هغۀ ووئيل چې، ”خو وګورئ، زۀ درې نه، بلکې څلور کسان وينم چې په اور کښې ګرځى، چې نۀ تړلے شوى دى او نۀ ورته څۀ نقصان رسېدلے دے او څلورم کس لکه د مقدسې فرښتې په شان ښکارى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_25.mp3', '', 1761754199, 1761754199),
(53302, 'Daniel 3:26', 'Daniel', 3, 26, 'نو بيا نبوکدنضر د اور د بټۍ خولې ته نزدې ورغلو او آواز ‎يې ورکړو، ”شدرک، ميشک او عبدنجو، د خُدائ تعالىٰ خِدمتګارانو، بهر راوځئ. دلته راشئ.“ نو شدرک، ميشک او عبدنجو د اور نه بهر راووتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_26.mp3', '', 1761754199, 1761754199),
(53303, 'Daniel 3:27', 'Daniel', 3, 27, 'نو بيا لوئ آفسران، سرکارى کسان، حکمرانان، او مشيران د هغوئ نه ګېرچاپېره راټول شول او وې ليدل چې اور بلکل د هغوئ بدن ته څۀ نقصان نۀ دے ورکړے، او نۀ د هغوئ د سر وېښتۀ راګونجى شوى دى، او د هغوئ چُوغې هم نۀ دى سوزېدلې، او د هغوئ د بدن نه د اور بوئ هم نۀ تلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_27.mp3', '', 1761754199, 1761754199),
(53304, 'Daniel 3:28', 'Daniel', 3, 28, 'نو بيا نبوکدنضر ووئيل، ”د شدرک، ميشک او د عبدنجو د خُدائ پاک ثنا‌ء دې وى چا چې خپله فرښته راولېږله او خپل خِدمتګاران يې بچ کړل. د هغوئ په هغۀ باندې ايمان وو او زما حکم يې د ‎پښو لاندې کړو او هغوئ دې ته تيار وُو چې د خُدائ پاک دپاره خپل ژوند د لاسه ورکړى نۀ دا چې د هغۀ په ځائ د بل معبود خِدمت او عبادت وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_28.mp3', '', 1761754199, 1761754199),
(53305, 'Daniel 3:29', 'Daniel', 3, 29, 'نو په دې وجه زۀ دا حکم جارى کوم چې د ټولو خلقو او قومونو او د هرې ژبې خلق کۀ چرې هغوئ د شدرک، ميشک او عبدنجو د خُدائ پاک خلاف څۀ ووائى نو هغوئ به ټوټې ټوټې شى او د هغوئ کورونه به تباه کړے شى، ځکه چې بل يو معبود هم داسې نشته چې څوک داسې بچ کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_29.mp3', '', 1761754199, 1761754199),
(53306, 'Daniel 3:30', 'Daniel', 3, 30, 'نو بيا بادشاه شدرک، ميشک او عبدنجو ته د بابل په صوبه کښې نور هم اوچت مقام ورکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel3_verse_30.mp3', '', 1761754199, 1761754199),
(53307, 'Jeremiah 37:1', 'Jeremiah', 37, 1, 'د يهوداه بادشاه يهوياکين د يهويقيم زوئ د تخت نه د راکوزولو نه وروستو د بابل بادشاه نبوکدنضر د هغۀ په ځائ صدقياه د يوسياه زوئ د يهوداه بادشاه مقرر کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_1.mp3', '', 1761754199, 1761754199),
(53308, 'Jeremiah 37:2', 'Jeremiah', 37, 2, 'نۀ خو صدقياه او نۀ د هغۀ خِدمتګارانو او نۀ په يهوداه کښې پاتې شوى خلقو د مالِک خُدائ په کلام عمل کولو کوم چې د يرمياه په وسيله اورولے شوے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_2.mp3', '', 1761754199, 1761754199),
(53309, 'Jeremiah 37:3', 'Jeremiah', 37, 3, 'خو بيا هم صدقياه بادشاه يهوکل د شلمياه زوئ او صفنياه اِمام د معسياه زوئ يوه ورځ دواړه يرمياه نبى ته ورولېږل او د هغۀ ته يې خواست وکړو چې، ”مونږ ته زمونږ د مالِک خُدائ نه دُعا وغواړه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_3.mp3', '', 1761754199, 1761754199),
(53310, 'Jeremiah 37:4', 'Jeremiah', 37, 4, 'تر اوسه يرمياه په قېدخانه کښې نۀ وو اچولے شوے او هر چرته چې يې زړۀ غوښتل هلته په خلقو کښې آزاد ګرځېدلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_4.mp3', '', 1761754199, 1761754199);